import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.BXzK3EA4.js";const p=JSON.parse('{"title":"거점과 영토","description":"","frontmatter":{},"headers":[],"relativePath":"world/Strongholds-and-Territory.md","filePath":"world/Strongholds-and-Territory.md"}'),s={name:"world/Strongholds-and-Territory.md"};function l(n,t,r,o,h,c){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="거점과-영토" tabindex="-1">거점과 영토 <a class="header-anchor" href="#거점과-영토" aria-label="Permalink to &quot;거점과 영토&quot;">​</a></h1><p><img src="https://github.com/islee23520/seoul-kenshi/blob/main/docs/assets/wiki/isometric-strongholds.svg?raw=true" alt="거점 점유와 통합의 아이소 공간"></p><p>거점 점유 후 안정화와 영토 통합을 4방향 시야와 연결로 관리합니다.</p><p>역은 점령 즉시 완성되는 깃발이 아니라 사람, 시설과 연결을 다시 작동시켜야 하는 전략 거점입니다. 아래 수치는 모두 첫 프로토타입용 <strong>설계 가정</strong>이며 플레이테스트로 조정합니다.</p><h2 id="입력과-출력" tabindex="-1">입력과 출력 <a class="header-anchor" href="#입력과-출력" aria-label="Permalink to &quot;입력과 출력&quot;">​</a></h2><table tabindex="0"><thead><tr><th>입력</th><th style="text-align:right;">범위·기본값</th><th>출력</th></tr></thead><tbody><tr><td>권위 <code>A</code></td><td style="text-align:right;">0~100, 점령 직후 최대 45</td><td>순찰, 협약 집행, 적대 활동 억제</td></tr><tr><td>협력 <code>L</code></td><td style="text-align:right;">0~100, 강제 점령 기본값 20</td><td>노동, 정보 제공, 통치 수용</td></tr><tr><td>시설 상태 <code>R</code></td><td style="text-align:right;">0~100</td><td>지역 서비스와 노선 서비스</td></tr><tr><td>연결도 <code>K</code></td><td style="text-align:right;">0~1</td><td>합법 경로의 최소 처리량</td></tr><tr><td>부족도 <code>S</code></td><td style="text-align:right;">0~1</td><td>식량·전력 중 더 심한 결핍</td></tr><tr><td>과확장 <code>O</code></td><td style="text-align:right;">0~2</td><td>모든 거점의 안정화와 수송 감점</td></tr></tbody></table><h2 id="계산-규칙" tabindex="-1">계산 규칙 <a class="header-anchor" href="#계산-규칙" aria-label="Permalink to &quot;계산 규칙&quot;">​</a></h2><p>합법적인 보급 경로마다 가장 좁은 연결의 처리율을 구하고 그중 가장 큰 값을 <code>K</code>로 사용합니다. 봉쇄된 연결은 삭제하지 않고 <code>K=0</code>의 원인과 복구 조건을 보존합니다.</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>K = clamp(max_path(min_edge_capacity), 0, 1)</span></span>
<span class="line"><span>충족률(공급, 수요) = 수요가 0이면 1, 아니면 clamp(공급/수요, 0, 1)</span></span>
<span class="line"><span>S = 1 - min(충족률(식량공급, 식량수요), 충족률(전력공급, 전력수요))</span></span></code></pre></div><p>수요가 0인 자원은 충족률 1, 즉 부족 기여 0으로 처리합니다. 이는 <a href="/world/Economy-and-Production.html">경제와 생산</a>의 부족률 규칙과 동일한 공유 규칙이며 어떤 경우에도 0으로 나누지 않습니다.</p><p>과확장 <code>O</code>는 <a href="/world/Logistics-and-Infrastructure.html">물류와 기반 시설</a>에 정의된 공유 0~2 척도를 그대로 사용합니다. 이 문서의 통치부담과 행정역량은 그 정의의 통치 부담 비율 <code>부담비율(통치부담, 행정역량)</code> 항으로 들어갑니다.</p><p>하루 정산 순서는 자원 배분 → 전투 결과 → 권위·협력·시설 → 단계 전이 → 사건 예약입니다. 동일한 입력은 항상 같은 결과를 냅니다.</p><h2 id="기본-수치" tabindex="-1">기본 수치 <a class="header-anchor" href="#기본-수치" aria-label="Permalink to &quot;기본 수치&quot;">​</a></h2><table tabindex="0"><thead><tr><th>규칙</th><th style="text-align:right;">기본값</th><th style="text-align:right;">최소</th><th style="text-align:right;">최대</th></tr></thead><tbody><tr><td>일반 역 시설 슬롯</td><td style="text-align:right;">2</td><td style="text-align:right;">1</td><td style="text-align:right;">4</td></tr><tr><td>환승역 시설 슬롯</td><td style="text-align:right;">3</td><td style="text-align:right;">1</td><td style="text-align:right;">4</td></tr><tr><td>주요 사업 작업량</td><td style="text-align:right;">100</td><td style="text-align:right;">40</td><td style="text-align:right;">240</td></tr><tr><td>통합 권위</td><td style="text-align:right;">65</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>통합 협력</td><td style="text-align:right;">55</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>통합 시설</td><td style="text-align:right;">60</td><td style="text-align:right;">0</td><td style="text-align:right;">100</td></tr><tr><td>통합 유지 기간</td><td style="text-align:right;">3일</td><td style="text-align:right;">1일</td><td style="text-align:right;">7일</td></tr></tbody></table><p>점령지는 <code>분쟁 → 점령 → 안정화 → 통합</code>을 거칩니다. <code>A&gt;=65</code>, <code>L&gt;=55</code>, <code>R&gt;=60</code>, <code>K&gt;=0.5</code>, <code>S&lt;=0.25</code>를 3일 연속 만족해야 통합됩니다.</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">stateDiagram-v2</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  [*] --&gt; 분쟁</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  분쟁 --&gt; 점령: 전투·협상 결과</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  점령 --&gt; 안정화: A&gt;=50, L&gt;=35</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  안정화 --&gt; 통합: 3일간 통합 조건 충족</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  통합 --&gt; 안정화: 부족·고립·과확장</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  안정화 --&gt; 점령: 권위 붕괴</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  점령 --&gt; 분쟁: 수비·통치 상실</span></span></code></pre></div><h2 id="경계-상황" tabindex="-1">경계 상황 <a class="header-anchor" href="#경계-상황" aria-label="Permalink to &quot;경계 상황&quot;">​</a></h2><ul><li>식량 또는 전력이 75% 미만이면 부족 상태가 붙고 권위·협력이 하락합니다.</li><li>완전 고립이면 수입·수출은 0이지만 현지 비축과 발전은 계속 작동합니다.</li><li>과확장은 영토 상한이 아니라 담당자, 주둔군과 연결 부족으로 발생합니다.</li><li>같은 날 여러 거점이 임계치를 넘으면 안정된 거점 ID 순서로 정산합니다.</li><li>무전력 시설만 있는 역은 전력 수요 0으로 처리하며, 이때 전력 충족률은 1이 되어 부족도 <code>S</code>를 올리지 않지만 전력 서비스가 생긴 것으로 보지도 않습니다.</li><li>압박 부채(<code>PressureDebt</code>)는 외부 사건 압박의 누적치이며, <strong>설계 가정</strong>으로 기본값 0·범위 0~100입니다. 권위·협력 저하와 가시성·적대 인접·과확장으로 쌓이고 주둔 커버와 연결도 <code>K</code>로 줄어들며, 부채가 100에 도달하면 원인에 맞는 사건을 하나 예약하고 부채 100을 뺍니다.</li></ul><h2 id="계산-예시" tabindex="-1">계산 예시 <a class="header-anchor" href="#계산-예시" aria-label="Permalink to &quot;계산 예시&quot;">​</a></h2><p>식량 40/100, 전력 60/100이면 <code>S = 1 - min(0.4, 0.6) = 0.6</code>입니다. 합법 경로가 없으면 <code>K=0</code>입니다. 통치부담 4.5와 행정역량 3이면 통치 부담 비율은 <code>4.5/3=1.5</code>이고, 물류·귀환 부담 비율이 그보다 작다면 <code>O=clamp(1.5-1,0,2)=0.5</code>입니다. 세 조건이 겹친 역은 통합 조건을 만족할 수 없고, 이미 통합된 역이라면 안정화 단계로 후퇴하며, 권위까지 붕괴하면 점령 단계로 더 물러납니다. 그래도 현지 식량·발전·수리반이 남아 있다면 복구는 계속됩니다.</p>`,20)])])}const y=e(s,[["render",l]]);export{p as __pageData,y as default};
